export const meta = {
  "slug": "phosphor-device-mobile",
  "family": "phosphor",
  "name": "device-mobile",
  "category": "Media",
  "motion": "bounce",
  "component": "createPhosphorDeviceMobileIcon"
};

export function createPhosphorDeviceMobileIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
